    [("<i>I go always</i>.", "<i>I always go</i>."), ("<i>I always am late</i>.", "Com to be, depois: <i>I am always late</i>."), ("<i>I don't never</i>.", "Sem negação dupla: <i>I never ...</i>")],
    "<p>No trabalho: <b>We usually deploy on Tuesdays</b>, <b>The job runs once a day</b>, <b>Tests rarely fail</b>, <b>Always back up the database before migrating</b>. Na documentação de agendamentos (cron), a frequência é central.</p>",
    [("Posição correta:", ["I eat usually fruit.", "I usually eat fruit.", "Usually I eat fruit always."], 1, "Antes do verbo."),
     ("“Duas vezes por mês”:", ["two times by month", "twice a month", "twice for month"], 1, "Expressão fixa."),
     ("Com <i>to be</i>:", ["She always is happy.", "She is always happy.", "Always she happy."], 1, "Depois do to be.")],
    ["<i>How often ...?</i>", "always → usually → often → sometimes → rarely → never.", "Antes do verbo, depois do <i>to be</i>; <i>once/twice a week</i> no fim."],
